def next_speaker(history, agents, policy="round_robin"):
    if policy == "round_robin":
        last = history[-1].sender if history else None
        names = [a.name for a in agents]
        i = (names.index(last) + 1) % len(names) if last else 0
        return agents[i]
    if policy == "reply_to":
        # whoever was addressed speaks next
        return next(a for a in agents if a.name == history[-1].recipient)
    raise ValueError("unknown policy")
# an explicit policy removes ambiguity about whose turn it is

# BAD: each agent rephrases the previous rephrase
note = original
for agent in [a, b, c]:
    note = agent.summarize(note)   # errors compound each hop

# GOOD: always carry the original alongside any summary
payload = {"source_of_truth": original, "summary": None}
for agent in [a, b, c]:
    payload["summary"] = agent.summarize(payload["source_of_truth"])
# every agent summarizes ground truth, not the last hop's guess
